export const dynamic = "force-dynamic";
export const revalidate = 0;

async function FeaturedProducts() {
  const perfumes = await getFeaturedPerfumes();

  if (perfumes === null) {
    return (
      <p className="featured-message" role="status">
        No pudimos cargar la selección en este momento. Puedes explorar el{" "}
        <Link href="/catalogo">catálogo completo</Link>.
      </p>
    );
  }

  if (perfumes.length === 0) {
    return (
      <p className="featured-message">
        Pronto añadiremos fragancias a esta selección. Mientras tanto, explora el{" "}
        <Link href="/catalogo">catálogo completo</Link>.
      </p>
    );
  }

  return (
    <div className="product-grid">
      {perfumes.map((p) => (
        <HomeProductCard key={p.id} product={p} />
      ))}
    </div>
  );
}

function FeaturedProductsFallback() {
  return (
    <div className="product-grid" aria-busy="true" aria-label="Cargando selección">
      {Array.from({ length: 4 }, (_, i) => (
    <div className="product-skeleton-card" key={i} aria-hidden="true">
      <div className="product-skeleton-image" />
      <div className="product-skeleton-line" />
      <div className="product-skeleton-line product-skeleton-line-short" />
        </div>
      ))}
    </div>
  );
}

